INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''natural dye'' as opposed to ''synthetic dye''?', '["Color derived from plant, animal, or mineral sources rather than manufactured through chemical synthesis","A dye that only works on synthetic fiber, never on natural fiber","A dye that requires no mordant or fixation step whatsoever","A dye that is always more wash-fast than any synthetic alternative"]'::jsonb, 'Color derived from plant, animal, or mineral sources rather than manufactured through chemical synthesis', 'Natural dyes come from naturally occurring sources (plants like indigo/madder, insects like cochineal, or minerals), historically used before synthetic dye chemistry was developed; they''re increasingly of interest again for sustainability/niche markets despite generally being more variable and often needing mordants.', 1, '{"natural-dye"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is a ''mordant'' used for in natural dyeing?', '["A chemical (often a metal salt) that helps bind natural dye onto fiber, since many natural dyes lack strong inherent fiber affinity","A synthetic dye that replaces the need for natural dye entirely","A finishing chemical applied only after natural dyeing is fully complete","A device used to physically stretch fabric during dyeing"]'::jsonb, 'A chemical (often a metal salt) that helps bind natural dye onto fiber, since many natural dyes lack strong inherent fiber affinity', 'Many natural dyes don''t have strong direct affinity for fiber on their own; a mordant (commonly a metal salt like alum) is applied to the fiber to form a chemical bridge that helps the natural dye attach and stay fixed to the fiber.', 2, '{"mordant","natural-dyeing"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is a general drawback of natural dyes compared to synthetic dyes in industrial textile production?', '["Greater batch-to-batch color variability and generally more limited color range/fastness compared to standardized synthetic dyes","Natural dyes always produce more consistent, brighter colors than any synthetic dye","Natural dyes require no water at all, unlike synthetic dyeing","There is no practical difference in consistency between natural and synthetic dyes"]'::jsonb, 'Greater batch-to-batch color variability and generally more limited color range/fastness compared to standardized synthetic dyes', 'Since natural dye sources (plants, insects) vary with growing conditions/harvest, achieving precisely consistent shade batch-to-batch is more challenging than with chemically standardized synthetic dyes, which also generally offer a much broader color range and often better fastness properties.', 2, '{"natural-dye-limitations"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is the purpose of an ''anti-static'' finish on synthetic fabric?', '["To reduce the buildup of static electricity, which synthetic (often hydrophobic) fibers are prone to generating through friction","To permanently remove all color from the fabric","To increase the fabric''s flammability intentionally","To make the fabric completely waterproof"]'::jsonb, 'To reduce the buildup of static electricity, which synthetic (often hydrophobic) fibers are prone to generating through friction', 'Hydrophobic synthetic fibers (like polyester) don''t conduct away static charge as readily as moisture-absorbing natural fibers, making them prone to static cling; anti-static finishes add conductive/moisture-attracting agents to help dissipate this charge.', 1, '{"anti-static-finish"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''UV protection finishing'' (UPF-enhancing treatment) designed to do for a fabric?', '["Increase the fabric''s ability to block/absorb ultraviolet radiation, reducing UV exposure to the skin of the wearer","Permanently change the fabric''s visible color under UV light for decorative effect","Remove all natural fiber content from the fabric","Increase the fabric''s water absorbency to the maximum extent possible"]'::jsonb, 'Increase the fabric''s ability to block/absorb ultraviolet radiation, reducing UV exposure to the skin of the wearer', 'UV-protective finishes (via UV-absorbing chemical treatments or sometimes just tighter weave/higher density) increase the fabric''s Ultraviolet Protection Factor (UPF), reducing the amount of UV radiation that passes through to reach the wearer''s skin.', 1, '{"uv-protection-finish"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What does ''antimicrobial finish'' aim to achieve on a textile product?', '["Inhibit the growth of bacteria/fungi on the fabric, which can help reduce odor and degradation from microbial activity","Permanently increase the fabric''s susceptibility to bacterial growth","Replace the need for any washing of the garment ever again","Add a permanent bright color derived from microbial pigments"]'::jsonb, 'Inhibit the growth of bacteria/fungi on the fabric, which can help reduce odor and degradation from microbial activity', 'Antimicrobial finishes (often silver-ion or other active agents) inhibit microorganism growth on the fabric surface, commonly used to reduce odor-causing bacteria (e.g., in sportswear/socks) and limit fabric degradation from microbial activity.', 1, '{"antimicrobial-finish"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'Why might a fabric intended for activewear/sportswear specifically combine a ''moisture-wicking'' finish/fiber structure with an antimicrobial treatment?', '["Wicking moves sweat away from the skin to the fabric surface for faster evaporation, while antimicrobial treatment addresses the bacteria that thrive in that resulting damp environment and cause odor","The two treatments have identical functions and are always redundant with each other","Moisture-wicking finishes always eliminate all bacteria on their own, making antimicrobial treatment unnecessary","Antimicrobial treatment prevents moisture-wicking from working at all, making the combination counterproductive"]'::jsonb, 'Wicking moves sweat away from the skin to the fabric surface for faster evaporation, while antimicrobial treatment addresses the bacteria that thrive in that resulting damp environment and cause odor', 'Moisture-wicking manages sweat by moving it away from skin for evaporation, but doesn''t itself prevent bacterial growth in the resulting damp fabric; combining it with antimicrobial treatment specifically targets the odor-causing bacteria that would otherwise thrive in that moist environment — the two finishes address complementary, different aspects of activewear performance.', 2, '{"moisture-wicking","antimicrobial","activewear"}'::text[]);
